from __future__ import annotations

from typing import Any

INPUT_SCHEMA = {
    "type": "object",
    "properties": {
        "file_path": {"type": "string"}
    },
    "required": ["file_path"]
}
INPUT_SCHEMA = {"type": "object", "properties": {"dry_run": {"type": "boolean"}}, "required": []}

import os
import subprocess
from shutil import which

def run(payload: dict) -> dict:
    file_path = payload.get('file_path')
    if not file_path:
        return {
            "ok": False,
            "error": "Missing 'file_path' in payload"
        }

    dry_run = payload.get('dry_run', False)
    if dry_run:
        return {
            "ok": True,
            "message": f"Would play audio file: {file_path}"
        }

    # Check for available players
    players = [which('powershell'), which('cmd')]
    player = next((p for p in players if p), None)

    if not player:
        return {
            "ok": False,
            "error": "No audio player found"
        }

    # Construct the command to play the audio file
    if player == which('powershell'):
        command = [player, '-Command', f'Add-Type -TypeDefinition @"using System; using System.Diagnostics; class AudioPlayer {{ public static void Play(string filePath) {{ Process.Start(new ProcessStartInfo("{file_path}", "") {{ UseShellExecute = true }}); }} }}"@; [AudioPlayer]::Play("{file_path}");']
    elif player == which('cmd'):
        command = [player, '/c', f'start {file_path}']

    if dry_run:
        return {
            "ok": True,
            "message": f"Would play audio file: {file_path} using {player}"
        }

    # Execute the command to play the audio file
    try:
        subprocess.run(command, check=True)
        return {
            "ok": True,
            "message": f"Audio file played successfully: {file_path}"
        }
    except subprocess.CalledProcessError as e:
        return {
            "ok": False,
            "error": f"Failed to play audio file: {e}",
            "details": str(e)
        }
